{
  "part": {
    "name": "Combination wrench-like plate (open-end + ring-end) with top recess",
    "description": "Single solid prismatic part (constant thickness in Y, 0..15mm) shaped like a wrench: an open U-jaw head on one end, a circular ring/boss with a through-hole on the other end, joined by a rectangular handle. A shallow rectangular recessed pocket is present on the top face along the handle.",
    "source_views": [
      "front",
      "back",
      "left",
      "right",
      "top",
      "bottom",
      "toprightiso"
    ],
    "symmetry_note": "Overall nearly symmetric about the mid-plane X=0 (left/right), but STEP shows slight asymmetry (e.g., left handle side at x≈-10.0935 vs right at x=10.0)."
  },
  "Section": [
    {
      "id": "SEC_OPEN",
      "name": "Open-end head (U-jaw) + shoulder blends",
      "features included": [
        "Open-end U-slot/jaw interface for hex/round fastener",
        "Two parallel jaw inner faces",
        "Slot bottom stop face",
        "Inner corner fillets between jaw walls and slot bottom",
        "Outer perimeter circular arcs (two large-radius cylindrical patches)",
        "Shoulder blend fillets transitioning from handle to head"
      ],
      "function intent": "Engage a fastener from the side and transmit torque; provide a stop/locating face in the throat; blend into the handle to reduce stress concentration.",
      "physical behavior": "Loads from the fastener contact on the jaw faces create bending in the jaw arms and torsion in the handle. The inner fillets reduce peak stress at the slot-bottom corners; the shoulder blends distribute bending stresses into the handle and reduce notch sensitivity.",
      "geometry": "Extruded plate head region with a U-shaped opening: two opposing vertical planar jaw walls (x=±10) connected by a flat slot-bottom plane (z=-110). Outer boundary formed by two large-radius cylindrical side surfaces (R≈25.8) plus smaller cylindrical blend surfaces (R=5) near the handle transition and slot internal corners.",
      "location": "One end of the part (negative Z end in STEP bbox, roughly z≈-150 to -110 for slot region and surrounding head mass).",
      "colour": {
        "R": 220,
        "G": 80,
        "B": 60
      },
      "major_faces": [
        {
          "face_code": "0017",
          "name": "Jaw inner wall (left)",
          "Brep_id": "FACE 20",
          "description": "Vertical planar face forming one inner side of the open-end slot (x=-10), spanning z≈-150..-115."
        },
        {
          "face_code": "0018",
          "name": "Slot inner-corner fillet (left)",
          "Brep_id": "FACE 19",
          "description": "Cylindrical fillet (R=5) blending left jaw wall into slot bottom near z≈-115..-110."
        },
        {
          "face_code": "0019",
          "name": "Slot bottom stop face",
          "Brep_id": "FACE 18",
          "description": "Flat planar throat/stop face of the open-end slot (z=-110), bridging between the inner-corner fillets."
        },
        {
          "face_code": "0020",
          "name": "Slot inner-corner fillet (right)",
          "Brep_id": "FACE 17",
          "description": "Cylindrical fillet (R=5) blending right jaw wall into slot bottom near z≈-115..-110."
        },
        {
          "face_code": "0021",
          "name": "Jaw inner wall (right)",
          "Brep_id": "FACE 22",
          "description": "Vertical planar face forming the other inner side of the open-end slot (x=+10), spanning z≈-150..-115."
        },
        {
          "face_code": "0025",
          "name": "Shoulder blend (left)",
          "Brep_id": "FACE 9",
          "description": "Cylindrical blend (R=5) transitioning from handle side into open head outer mass on the left side near z≈-101..-96."
        },
        {
          "face_code": "0024",
          "name": "Outer arc (left)",
          "Brep_id": "FACE 23",
          "description": "Large cylindrical outer perimeter surface of the open head on the left side (R≈25.97), covering z≈-150..-101."
        },
        {
          "face_code": "0022",
          "name": "Outer arc (right)",
          "Brep_id": "FACE 16",
          "description": "Large cylindrical outer perimeter surface of the open head on the right side (R≈25.79), covering z≈-150..-101."
        },
        {
          "face_code": "0023",
          "name": "Shoulder blend (right)",
          "Brep_id": "FACE 15",
          "description": "Cylindrical blend (R=5) transitioning from handle side into open head outer mass on the right side near z≈-101..-96."
        }
      ],
      "minor_faces_Brep_id": [],
      "relationships": [
        {
          "source id": "SEC_OPEN",
          "target id": "SEC_HANDLE",
          "function relationship": "transmits_load",
          "structural relationship": "attached_to"
        },
        {
          "source id": "SEC_OPEN",
          "target id": "SEC_HANDLE",
          "function relationship": "distributes_stress",
          "structural relationship": "blends_into"
        }
      ]
    },
    {
      "id": "SEC_HANDLE",
      "name": "Handle / main plate body (including global top & bottom faces)",
      "features included": [
        "Main torque-transmitting handle beam",
        "Global top planar face",
        "Global bottom planar face",
        "Two long handle side faces"
      ],
      "function intent": "Provide lever arm length and stiffness to transmit torque between the two end interfaces; provide overall planar reference faces for manufacturing/assembly contact.",
      "physical behavior": "Carries torsional shear and bending from end loads; its prismatic thickness resists out-of-plane bending. The large top/bottom planes provide stiffness and define thickness; long side planes bound the main web.",
      "geometry": "Constant-thickness extruded plate. Globally planar top (y=15) and bottom (y=0) faces across the entire part; handle region bounded by two long vertical side planes at approximately x=+10 and x≈-10.0935.",
      "location": "Central span between heads (dominant mid-length along Z), forming the backbone of the part.",
      "colour": {
        "R": 70,
        "G": 150,
        "B": 210
      },
      "major_faces": [
        {
          "face_code": "0000",
          "name": "Top face (global)",
          "Brep_id": "FACE 24",
          "description": "Global planar top surface at y=15, includes outer perimeter and openings/recess boundaries."
        },
        {
          "face_code": "0002",
          "name": "Handle side (right)",
          "Brep_id": "FACE 14",
          "description": "Long vertical planar side of handle at x=+10, spanning y=0..15 and much of the handle Z-length."
        },
        {
          "face_code": "0001",
          "name": "Bottom face (global)",
          "Brep_id": "FACE 25",
          "description": "Global planar bottom surface at y=0, includes outer perimeter and through-hole boundaries."
        },
        {
          "face_code": "0003",
          "name": "Handle side (left)",
          "Brep_id": "FACE 10",
          "description": "Long vertical planar side of handle at x≈-10.0935, spanning y=0..15 and much of the handle Z-length."
        }
      ],
      "minor_faces_Brep_id": [],
      "relationships": [
        {
          "source id": "SEC_HANDLE",
          "target id": "SEC_OPEN",
          "function relationship": "transmits_load",
          "structural relationship": "supports"
        },
        {
          "source id": "SEC_HANDLE",
          "target id": "SEC_RING",
          "function relationship": "transmits_load",
          "structural relationship": "supports"
        },
        {
          "source id": "SEC_HANDLE",
          "target id": "SEC_POCKET",
          "function relationship": "provides_clearance",
          "structural relationship": "contained_in"
        }
      ]
    },
    {
      "id": "SEC_RING",
      "name": "Ring-end head (closed circular boss with through-hole) + neck blends",
      "features included": [
        "Ring-end through-hole interface",
        "Outer ring boss cylindrical perimeter",
        "Neck/shoulder blends into handle"
      ],
      "function intent": "Constrain a fastener on all sides (closed ring) to transmit higher torque with reduced slip; provide a robust boss around the through-hole; smoothly transition loads into the handle.",
      "physical behavior": "Fastener contact loads create circumferential compression and local bearing around the hole; torque generates shear flow in the ring wall. Outer boss resists ovalization; neck blends lower stress at the handle junction.",
      "geometry": "Circular boss at one end with an internal cylindrical through-hole (R=10). External perimeter is a cylindrical surface (R≈14.92). Two smaller cylindrical blend patches (R=5) appear at the transition from handle width to boss.",
      "location": "Opposite end from the open head (positive Z end in STEP bbox, around z≈0..26).",
      "colour": {
        "R": 120,
        "G": 200,
        "B": 110
      },
      "major_faces": [
        {
          "face_code": "0015",
          "name": "Ring neck blend (left)",
          "Brep_id": "FACE 11",
          "description": "Cylindrical blend surface (R=5) at ring/handle transition on the left side near z≈-2..+1."
        },
        {
          "face_code": "0013",
          "name": "Outer ring perimeter",
          "Brep_id": "FACE 12",
          "description": "Outer cylindrical surface of ring boss (R≈14.922), axis along Y."
        },
        {
          "face_code": "0016",
          "name": "Ring neck blend (right)",
          "Brep_id": "FACE 13",
          "description": "Cylindrical blend surface (R=5) at ring/handle transition on the right side near z≈-2..+1."
        },
        {
          "face_code": "0014",
          "name": "Ring through-hole",
          "Brep_id": "FACE 21",
          "description": "Inner cylindrical surface of the ring-end through-hole (R=10), axis along Y."
        }
      ],
      "minor_faces_Brep_id": [],
      "relationships": [
        {
          "source id": "SEC_RING",
          "target id": "SEC_HANDLE",
          "function relationship": "transmits_load",
          "structural relationship": "attached_to"
        },
        {
          "source id": "SEC_RING",
          "target id": "SEC_HANDLE",
          "function relationship": "distributes_stress",
          "structural relationship": "blends_into"
        }
      ]
    },
    {
      "id": "SEC_POCKET",
      "name": "Top recessed pocket (shallow rectangular cavity with corner fillets)",
      "features included": [
        "Shallow recessed pocket on top face",
        "Pocket floor (planar)",
        "Pocket side walls (planar)",
        "Corner fillets (R=1) at the four pocket corners"
      ],
      "function intent": "Provide a recessed area for weight reduction, label/marking, or grip/clearance while keeping the bottom face flat.",
      "physical behavior": "Removes material locally, slightly reducing bending stiffness in the handle midspan; filleted corners reduce stress concentration compared with sharp internal corners.",
      "geometry": "Rectangular pocket recessed by ~1mm from the top face (pocket bottom at y=14, top at y=15). Bounded by two long side walls in X and two end walls in Z, with four quarter-cylinder corner fillets (R=1), all extruded along Y.",
      "location": "On the top face along the handle length, between ring and open heads (approximately z≈-97 to z≈-6).",
      "colour": {
        "R": 200,
        "G": 170,
        "B": 60
      },
      "major_faces": [
        {
          "face_code": "0004",
          "name": "Pocket floor",
          "Brep_id": "FACE 1",
          "description": "Planar bottom of the recess at y=14."
        },
        {
          "face_code": "0005",
          "name": "Pocket left long wall",
          "Brep_id": "FACE 7",
          "description": "Left vertical wall of pocket (x≈-7.491), spanning y=14..15 along pocket length."
        },
        {
          "face_code": "0006",
          "name": "Pocket back-left corner fillet",
          "Brep_id": "FACE 6",
          "description": "Quarter-cylinder corner fillet (R=1) at left/back corner of pocket."
        },
        {
          "face_code": "0007",
          "name": "Pocket back end wall",
          "Brep_id": "FACE 8",
          "description": "Vertical end wall of pocket at the back end (z≈-97.400)."
        },
        {
          "face_code": "0008",
          "name": "Pocket back-right corner fillet",
          "Brep_id": "FACE 3",
          "description": "Quarter-cylinder corner fillet (R=1) at right/back corner of pocket."
        },
        {
          "face_code": "0009",
          "name": "Pocket right long wall",
          "Brep_id": "FACE 4",
          "description": "Right vertical wall of pocket (x≈+6.945), spanning y=14..15 along pocket length."
        },
        {
          "face_code": "0010",
          "name": "Pocket front-right corner fillet",
          "Brep_id": "FACE 5",
          "description": "Quarter-cylinder corner fillet (R=1) at right/front corner of pocket."
        },
        {
          "face_code": "0011",
          "name": "Pocket front end wall",
          "Brep_id": "FACE 2",
          "description": "Vertical end wall of pocket at the front end (z≈-6.152)."
        },
        {
          "face_code": "0012",
          "name": "Pocket front-left corner fillet",
          "Brep_id": "FACE 0",
          "description": "Quarter-cylinder corner fillet (R=1) at left/front corner of pocket."
        }
      ],
      "minor_faces_Brep_id": [],
      "relationships": [
        {
          "source id": "SEC_POCKET",
          "target id": "SEC_HANDLE",
          "function relationship": "provides_clearance",
          "structural relationship": "contained_in"
        },
        {
          "source id": "SEC_POCKET",
          "target id": "SEC_HANDLE",
          "function relationship": "distributes_stress",
          "structural relationship": "offset_from"
        }
      ]
    }
  ]
}
